cudaEventElapsedTime(&elapsedTime, start, stop);
std::cout << "Kernel execution time: " << elapsedTime << " ms" << std::endl;

cudaEventDestroy(start);
cudaEventDestroy(stop);
cudaStreamDestroy(stream);
```

### 2.5.3.4 Checking Event Status

**Blocking** — `cudaEventSynchronize()` waits until the event completes (here: kernel 1 guaranteed done, then launch a dependent CPU task while kernel 2 may still run):

```cpp
cudaEvent_t event;
cudaStream_t stream;

cudaStreamCreate(&stream);
cudaEventCreate(&event);

kernel<<<grid, block, 0, stream>>>(...);
cudaEventRecord(event, stream);
kernel2<<<grid, block, 0, stream>>>(...);

// Kernel 1 guaranteed complete; launch dependent task
cudaEventSynchronize(event);
dependentCPUtask();

// Kernel 2 guaranteed complete
cudaStreamSynchronize(stream);

cudaEventDestroy(event);
cudaStreamDestroy(stream);
```

**Non-blocking (polling)** — `cudaEventQuery()`. This example demonstrates **overlap of CPU work + GPU kernel execution + device-to-host copy**: kernel1 produces data; an event follows it; kernel2 runs after; the CPU polls the event and launches the D2H copy in a *second* stream once kernel1 finishes:

```cpp
cudaEvent_t event;
cudaStream_t stream1;
cudaStream_t stream2;

size_t size = LARGE_NUMBER;
float* d_data;
float* h_data;

cudaMalloc(&d_data, size);
cudaMallocHost(&h_data, size);          // pinned host buffer

cudaStreamCreate(&stream1);   // Processing stream
cudaStreamCreate(&stream2);   // Copying stream
bool copyStarted = false;

cudaEventCreate(&event);

kernel1<<<grid, block, 0, stream1>>>(d_data, size);
cudaEventRecord(event, stream1);        // event after kernel1
kernel2<<<grid, block, 0, stream1>>>();

// Overlap CPU work with GPU work; peek for kernel1 completion
while ( not allCPUWorkDone() || not copyStarted ) {
    doNextChunkOfCPUWork();

    if ( not copyStarted ) {
        if( cudaEventQuery(event) == cudaSuccess ) {
            cudaMemcpyAsync(h_data, d_data, size, cudaMemcpyDeviceToHost, stream2);
            copyStarted = true;
        }
    }
}

cudaStreamSynchronize(stream1);
cudaStreamSynchronize(stream2);

cudaEventDestroy(event);
cudaStreamDestroy(stream1);
cudaStreamDestroy(stream2);
cudaFree(d_data);
free(h_data);
```

---

## 2.5.4 Callback Functions from Streams

Two functions launch host functions from a stream: **`cudaLaunchHostFunc()`** (preferred) and **`cudaStreamAddCallback()`** (**slated for deprecation**).

### `cudaLaunchHostFunc()`

```cpp
cudaError_t cudaLaunchHostFunc(cudaStream_t stream, void (*func)(void *), void *data);
```

- `stream` — target stream; `func` — callback; `data` — user data pointer

Callback signature:

```cpp
void hostFunction(void *data);
```

**Caveat**: the host function **may not call any CUDA APIs**.

**Execution guarantees (relevant to unified memory):**
- The stream is considered **idle** during the function's execution — it may use memory attached to its stream.
- The function's start has the same effect as synchronizing an event recorded just before it (synchronizes "joined" streams).
- Adding device work to any stream does **not** make the stream active until all preceding host functions/callbacks have executed.
- Function completion doesn't make the stream active except as above; the stream stays idle across consecutive host functions without interleaved device work (enabling stream sync by signaling from a host function at stream end).

### 2.5.4.1 `cudaStreamAddCallback()` (deprecated)

```cpp
cudaError_t cudaStreamAddCallback(cudaStream_t stream, cudaStreamCallback_t callback, void* userData, unsigned int flags);
```

- `flags` must currently be **0**.

Callback signature:

```cpp
void callbackFunction(cudaStream_t stream, cudaError_t status, void *userData);
```

`status` carries the stream's current error state. Same restrictions: stream stays inactive until the callback completes; no CUDA calls inside.

### 2.5.4.2 Asynchronous Error Handling

Stream errors may not surface until synchronization. Two query functions:

- **`cudaGetLastError()`** — returns **and clears** the last error in the current context (a second immediate call returns `cudaSuccess` if nothing new occurred)
- **`cudaPeekAtLastError()`** — returns the last error **without clearing**

Both return `cudaError_t`; printable names via `cudaGetErrorName()` / `cudaGetErrorString()`:

```cpp
cudaStreamSynchronize(stream);

// Peek without clearing
cudaError_t err = cudaPeekAtLastError();
if (err != cudaSuccess) {
    printf("Error with name: %s\n", cudaGetErrorName(err));
    printf("Error description: %s\n", cudaGetErrorString(err));
}

// Get and clear
cudaError_t err2 = cudaGetLastError();
if (err2 != cudaSuccess) {
    printf("Error with name: %s\n", cudaGetErrorName(err2));
    printf("Error description: %s\n", cudaGetErrorString(err2));
}

if (err2 != err) {
    printf("As expected, cudaPeekAtLastError() did not clear the error\n");
}

cudaError_t err3 = cudaGetLastError();
if (err3 == cudaSuccess) {
    printf("As expected, cudaGetLastError() cleared the error\n");
}
```

> **💡 Debugging tip**: Set environment variable **`CUDA_LAUNCH_BLOCKING=1`** to synchronize after every kernel launch — helps pinpoint which kernel/transfer caused an error. Note: this can make applications run **substantially slower**.

---

## 2.5.5 CUDA Stream Ordering

CUDA streams are **in-order streams**: execution order matches enqueue order; operations cannot leap-frog each other. Memory operations are tracked by the runtime and complete before the next operation, giving dependent kernels safe data access.

**Exceptions (relaxed semantics for optimization):**
- **Programmatic dependent kernel launch** — overlapping two kernels via special attributes
- **Asynchronous batched memory copy** — runtime may perform non-overlapping batch copies concurrently

---

## 2.5.6 Blocking/Non-Blocking Streams and the Default Stream

Two stream types; the terms refer **only to synchronization with the default stream**. `cudaStreamCreate()` produces **blocking** streams by default. Create non-blocking with:

```cpp
cudaStream_t stream;
cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking);
```

Destroy normally with `cudaStreamDestroy()`.

### 2.5.6.1 Legacy Default Stream (NULL stream / stream ID 0)

Used when no stream is specified (kernel launches, blocking `cudaMemcpy()`). Shared among all host threads; it is a **blocking** stream — an operation in it **synchronizes with all other blocking streams** (waits for them to complete first).

**With blocking streams — serialized execution** (kernel2 waits for kernel1; kernel3 waits for kernel2, even though all could run concurrently):

```cpp
cudaStream_t stream1, stream2;
cudaStreamCreate(&stream1);
cudaStreamCreate(&stream2);

kernel1<<<grid, block, 0, stream1>>>(...);
kernel2<<<grid, block>>>(...);              // default stream
kernel3<<<grid, block, 0, stream2>>>(...);

cudaDeviceSynchronize();
```

**With non-blocking streams — potential full concurrency** (default stream no longer synchronizes; no execution ordering can be assumed → explicit sync needed):

```cpp
cudaStream_t stream1, stream2;
cudaStreamCreateWithFlags(&stream1, cudaStreamNonBlocking);
cudaStreamCreateWithFlags(&stream2, cudaStreamNonBlocking);

kernel1<<<grid, block, 0, stream1>>>(...);
kernel2<<<grid, block>>>(...);
kernel3<<<grid, block, 0, stream2>>>(...);

cudaDeviceSynchronize();
```

### 2.5.6.2 Per-thread Default Stream (since CUDA 7)

Each host thread gets its own independent default stream via:
- nvcc option: **`--default-stream per-thread`**, or
- Preprocessor macro: **`CUDA_API_PER_THREAD_DEFAULT_STREAM`**

Behavior then matches the non-blocking stream example (no cross-stream serialization with the default stream).

---

## 2.5.7 Explicit Synchronization

| Function | Behavior |
|---|---|
| `cudaDeviceSynchronize()` | Waits for **all** preceding commands in **all streams of all host threads** |
| `cudaStreamSynchronize(stream)` | Waits for all preceding commands in the **given stream** (other streams keep running) |
| `cudaStreamWaitEvent(stream, event)` | Commands added to `stream` after this call **delay until `event` completes** (cross-stream dependency) |
| `cudaStreamQuery(stream)` | Reports whether all preceding commands in a stream have completed |

---

## 2.5.8 Implicit Synchronization

Operations from different streams **cannot run concurrently** if any operation on the NULL stream is submitted between them — **unless** the streams are non-blocking (`cudaStreamNonBlocking`).

**Guidelines for maximizing concurrent kernel execution:**
1. Issue all **independent operations before dependent** ones
2. **Delay synchronization** as long as possible

---

## 2.5.9 Miscellaneous and Advanced Topics

### 2.5.9.1 Stream Prioritization

Created via `cudaStreamCreateWithPriority()`. **Lower numbers = higher priority.** Query range with `cudaDeviceGetStreamPriorityRange()`. Default priority is **0**.

```cpp
int minPriority, maxPriority;

cudaDeviceGetStreamPriorityRange(&minPriority, &maxPriority);

// cudaStreamDefault = blocking w.r.t. legacy default stream
// (cudaStreamNonBlocking also allowed)
cudaStream_t stream1, stream2;
cudaStreamCreateWithPriority(&stream1, cudaStreamDefault, minPriority);  // Lowest priority
cudaStreamCreateWithPriority(&stream2, cudaStreamDefault, maxPriority);  // Highest priority
```

> Priority is only a **hint**, applies mainly to **kernel launches** (may not be respected for memory transfers), does **not preempt** running work, and guarantees no execution order.

### 2.5.9.2 Introduction to CUDA Graphs with Stream Capture

Multiple streams + `cudaStreamWaitEvent` can express a full **DAG** of operations. For DAGs executed many times, **CUDA Graphs** reduce launch latency/CPU overhead:

1. **Capture** the graph (once) — or compose manually via the graph API
2. **Instantiate** (once) — sets up runtime structures for fastest launch
3. **Execute** repeatedly with minimized CPU overhead

```cpp
#define N 500000 // tuned such that kernel takes a few microseconds

__global__ void shortKernel(float * out_d, float * in_d){
    int idx=blockIdx.x*blockDim.x+threadIdx.x;
    if(idx<N) out_d[idx]=1.23*in_d[idx];
}

bool graphCreated=false;
cudaGraph_t graph;
cudaGraphExec_t instance;

for(int istep=0; istep<NSTEP; istep++){
    if(!graphCreated){
        // Capture the graph
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeGlobal);

        for(int ikrnl=0; ikrnl<NKERNEL; ikrnl++){
            shortKernel<<<blocks, threads, 0, stream>>>(out_d, in_d);
        }

        cudaStreamEndCapture(stream, &graph);

        // Instantiate the graph
        cudaGraphInstantiate(&instance, graph, NULL, NULL, 0);
        graphCreated=true;
    }

    cudaGraphLaunch(instance, stream);   // Launch the graph
    cudaStreamSynchronize(stream);       // Synchronize
}
```

---

## 2.5.10 Summary of Asynchronous Execution

> - Async APIs express concurrent/overlapping execution; actual concurrency depends on hardware resources and compute capability.
> - Key abstractions: **streams, events, callback functions**.
> - Synchronization possible at **event, stream, and device** level.
> - The **default stream is blocking** — synchronizes with all blocking streams, but not with non-blocking streams.
> - Default-stream behavior avoidable via per-thread default streams (`--default-stream per-thread` or `CUDA_API_PER_THREAD_DEFAULT_STREAM`).
> - Stream **priorities** are hints; may not apply to memory transfers.
> - Overhead-reduction APIs: **CUDA Graphs, Batched Memory Transfers, Programmatic Dependent Kernel Launch**.

---

